#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// Expecting a timestamp, a key or a word.
    Item,
    /// Just consumed a key and its `=`; expecting the value.
    Value,
    /// Finished, either at the end of the line or after an error.
    Done,
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Item }
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

/// A successfully scanned token, the offset just after it and the state to continue in.
type Scan<'a> = Result<(Token<'a>, usize, State), LexError>;

#[inline(always)]
fn is_blank(c: u8) -> bool {
    c == b' ' || c == b'\\t'
}

/// A token that ends at `end` (exclusive) must be followed by a blank or the end of the line.
#[inline(always)]
fn expect_separator(b: &[u8], end: usize) -> Result<(), LexError> {
    match b.get(end) {
        Some(&c) if !is_blank(c) => Err(LexError::ExpectedSeparator { pos: end }),
        _ => Ok(()),
    }
}

/// `[timestamp]`, with `p` at the opening bracket.
fn scan_timestamp<'a>(src: &'a str, p: usize) -> Scan<'a> {
    let b = src.as_bytes();
    let start = p + 1;
    let mut i = start;
    loop {
        match b.get(i) {
            None => return Err(LexError::UnterminatedTimestamp { pos: p }),
            Some(b']') => break,
            Some(b'[') => return Err(LexError::NestedBracket { pos: i }),
            Some(_) => i += 1,
        }
    }
    expect_separator(b, i + 1)?;
    Ok((Token::Timestamp(&src[start..i]), i + 1, State::Item))
}

/// A key (`name=`) or a plain word, with `p` at its first character.
fn scan_key_or_word<'a>(src: &'a str, p: usize) -> Scan<'a> {
    let b = src.as_bytes();
    let mut i = p;
    while i < b.len() && !is_blank(b[i]) && b[i] != b'=' {
        if b[i] == b'"' {
            return Err(LexError::UnexpectedQuote { pos: i });
        }
        i += 1;
    }
    if i < b.len() && b[i] == b'=' {
        Ok((Token::Key(&src[p..i]), i + 1, State::Value))
    } else {
        Ok((Token::Word(&src[p..i]), i, State::Item))
    }
}

/// `"quoted"`, with `p` at the opening quote.
fn scan_quoted<'a>(src: &'a str, p: usize) -> Scan<'a> {
    let b = src.as_bytes();
    let start = p + 1;
    let mut i = start;
    loop {
        match b.get(i) {
            None => return Err(LexError::UnterminatedQuote { pos: p }),
            Some(b'"') => break,
            Some(b'\\\\') => match b.get(i + 1) {
                None => return Err(LexError::UnterminatedQuote { pos: p }),
                Some(b'"' | b'\\\\' | b'n' | b't') => i += 2,
                Some(_) => return Err(LexError::InvalidEscape { pos: i }),
            },
            Some(_) => i += 1,
        }
    }
    expect_separator(b, i + 1)?;
    Ok((Token::Quoted(&src[start..i]), i + 1, State::Item))
}

/// An unquoted value, possibly empty, with `p` at its first character.
fn scan_bare<'a>(src: &'a str, p: usize) -> Scan<'a> {
    let b = src.as_bytes();
    let mut i = p;
    while i < b.len() && !is_blank(b[i]) {
        if b[i] == b'"' {
            return Err(LexError::UnexpectedQuote { pos: i });
        }
        i += 1;
    }
    Ok((Token::Bare(&src[p..i]), i, State::Item))
}

impl<'a> Tokens<'a> {
    /// Scans the next token from the current position.
    fn scan(&self) -> Option<Scan<'a>> {
        let src = self.src;
        let b = src.as_bytes();
        let mut p = self.pos;
        match self.state {
            State::Item => {
                while p < b.len() && is_blank(b[p]) {
                    p += 1;
                }
                match b.get(p)? {
                    b'[' => Some(scan_timestamp(src, p)),
                    b'"' => Some(Err(LexError::UnexpectedQuote { pos: p })),
                    b'=' => Some(Err(LexError::EmptyKey { pos: p })),
                    _ => Some(scan_key_or_word(src, p)),
                }
            }
            State::Value => Some(match b.get(p) {
                None => Ok((Token::Bare(&src[p..p]), p, State::Item)),
                Some(&c) if is_blank(c) => Ok((Token::Bare(&src[p..p]), p, State::Item)),
                Some(b'"') => scan_quoted(src, p),
                Some(_) => scan_bare(src, p),
            }),
            State::Done => None,
        }
    }
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        match self.scan() {
            Some(Ok((token, pos, state))) => {
                self.pos = pos;
                self.state = state;
                Some(Ok(token))
            }
            Some(Err(err)) => {
                self.pos = self.src.len();
                self.state = State::Done;
                Some(Err(err))
            }
            None => {
                // Only reachable at the end of the line (or already done): skip trailing blanks.
                self.pos = self.pos.max(self.trailing_pos());
                None
            }
        }
    }
}
